def to_tool(e: dict) -> dict:
    """Convierte una entrada del catálogo en los campos de una herramienta del portal."""
    inst = []
    if e.get("k"):
        inst.append(f"**Kali Linux** (incluida o en su repositorio) · [ficha en kali.org](https://www.kali.org/tools/{e['k']}/)\n\n```bash\nsudo apt update && sudo apt install -y {e['k']}\n```")
    if e.get("i"):
        inst.append(f"**Instalación:** {e['i']}")
    if e.get("gh") and not e.get("k") and not e.get("i"):
        inst.append(f"**Instalación:** descarga la última versión en [Releases]({e['gh']}/releases) o sigue el README del repositorio.")
    if e.get("web"):
        inst.append(f"**Sitio oficial:** [{e['web']}]({e['web']})")
    auth = ("Herramienta intrusiva: úsala solo contra sistemas de ACME o de instituciones que lo hayan autorizado por escrito, "
            "dentro de una ventana acordada y con aprobación del responsable de seguridad.") if e.get("a") else ""
    usage = "## Instalación\n" + "\n\n".join(inst) + "\n\n## Uso en el SOC\n" + e["d"] + \
            ("\n\n> ⚠️ " + auth if auth else "") + "\n\nCompleta esta sección con los comandos y procedimientos internos del equipo."
    return {"name": e["n"], "category": e["c"], "repo_url": e.get("gh") or e.get("web") or "", "homepage": e.get("web") or "",
            "platform": e["p"], "language": e.get("l") if e.get("l") != "—" else "", "description": e["d"], "tags": e.get("t", ""),
            "requires_auth": 1 if e.get("a") else 0, "auth_note": auth, "status": "En evaluación" if e.get("a") else "Aprobada",
            "usage": usage, "owner": ""}
